    runtime_move_forward[0] = binding->move_key_forward;
    runtime_move_forward[1] = binding->move_key_backward;
    runtime_move_forward[2] = binding->turn_key_left;
    runtime_move_forward[3] = binding->turn_key_right;
    runtime_move_forward[4] = binding->fire_key;
    runtime_move_forward[5] = binding->key_reserved_0;
    runtime_move_forward[6] = binding->key_reserved_1;
    runtime_move_forward[7] = binding->aim_key_left;
    runtime_move_forward[8] = binding->aim_key_right;
